import subprocess

def safe_pdf_to_text(pdf_path):
    try:
        result = subprocess.run(['pdftotext', pdf_path, '-'], capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error: {e}")
        return None

# Example usage
print(safe_pdf_to_text('example.pdf'))

import subprocess

def convert_pdf_to_text(file_path):
    try:
        result = subprocess.run(['pdftotext', file_path, '-'], capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError:
        return 'Failed to convert PDF'

# Example usage
print(convert_pdf_to_text('example.pdf'))
